161	          out[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
162	              (nnei - jj) * var * ll[0];
163	          out[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
164	              (nnei - jj) * var * ll[1];
165	          out[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
166	              (nnei - jj) * var * ll[2];
167	          out[ii * last_layer_size * 4 + 3 * last_layer_size + kk] +=
168	              (nnei - jj) * var * ll[3];
169	        } else {
170	          out[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
171	              var * ll[0];
172	          out[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
173	              var * ll[1];
174	          out[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
175	              var * ll[2];
176	          out[ii * last_layer_size * 4 + 3 * last_layer_size + kk] +=
177	              var * ll[3];
178	        }
179	      }
180	      if (unloop) {
181	        break;
182	      }
183	    }
184	  }
185	}
