187	template <typename FPTYPE>
188	void deepmd::tabulate_fusion_se_a_grad_cpu(FPTYPE* dy_dem_x,
189	                                           FPTYPE* dy_dem,
190	                                           FPTYPE* dy_dtwo,
191	                                           const FPTYPE* table,
192	                                           const FPTYPE* table_info,
193	                                           const FPTYPE* em_x,
194	                                           const FPTYPE* em,
195	                                           const FPTYPE* two_embed,
196	                                           const FPTYPE* dy,
197	                                           const int nloc,
198	                                           const int nnei,
199	                                           const int last_layer_size,
200	                                           const bool is_sorted) {
201	  bool enable_se_atten = two_embed != nullptr;
202	  memset(dy_dem_x, 0, sizeof(FPTYPE) * nloc * nnei);
203	  memset(dy_dem, 0, sizeof(FPTYPE) * nloc * nnei * 4);
204	  if (enable_se_atten) {
205	    memset(dy_dtwo, 0, sizeof(FPTYPE) * nloc * nnei * last_layer_size);
206	  }
207	  FPTYPE const lower = table_info[0];
208	  FPTYPE const upper = table_info[1];
209	  FPTYPE const _max = table_info[2];
210	  FPTYPE const stride0 = table_info[3];
211	  FPTYPE const stride1 = table_info[4];
212	// for every atom, execute a small gemm~
213	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
214	#pragma omp parallel for
215	  for (int ii = 0; ii < nloc; ii++) {
216	    FPTYPE ll[4];
217	    FPTYPE rr[4];
218	    FPTYPE ago = em_x[ii * nnei + nnei - 1];
219	    bool unloop = false;
220	    for (int jj = 0; jj < nnei; jj++) {
221	      // construct the dy/dx
222	      ll[0] = em[ii * nnei * 4 + jj * 4 + 0];
223	      ll[1] = em[ii * nnei * 4 + jj * 4 + 1];
224	      ll[2] = em[ii * nnei * 4 + jj * 4 + 2];
225	      ll[3] = em[ii * nnei * 4 + jj * 4 + 3];
226	      FPTYPE xx = em_x[ii * nnei + jj];
227	      if (ago == xx && ll[1] == 0. && ll[2] == 0. && ll[3] == 0. && is_sorted) {
228	        unloop = true;
229	      }
230	      int table_idx = 0;
231	      locate_xx(lower, upper, _max, stride0, stride1, xx, table_idx);
232	      FPTYPE grad = (FPTYPE)0.0;
233	      for (int kk = 0; kk < last_layer_size; kk++) {
234	        rr[0] = dy[ii * last_layer_size * 4 + 0 * last_layer_size + kk];
235	        rr[1] = dy[ii * last_layer_size * 4 + 1 * last_layer_size + kk];
236	        rr[2] = dy[ii * last_layer_size * 4 + 2 * last_layer_size + kk];
237	        rr[3] = dy[ii * last_layer_size * 4 + 3 * last_layer_size + kk];
238	        FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * kk + 0];
239	        FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * kk + 1];
240	        FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * kk + 2];
241	        FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * kk + 3];
242	        FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * kk + 4];
243	        FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * kk + 5];
244	        FPTYPE res =
245	            a0 + (a1 + (a2 + (a3 + (a4 + a5 * xx) * xx) * xx) * xx) * xx;
246	        FPTYPE g =
247	            (a1 + (2 * a2 + (3 * a3 + (4 * a4 + 5 * a5 * xx) * xx) * xx) * xx);
248	        FPTYPE resold = res;
249	        if (enable_se_atten) {
250	          FPTYPE t = two_embed[ii * nnei * last_layer_size +
251	                               jj * last_layer_size + kk];
252	          res = res * t + res;
253	          g += t * g;
254	        }
255	
256	        FPTYPE dotllrr = dot(ll, rr);
257	        if (unloop) {
258	          grad += g * dotllrr * (nnei - jj);
259	          dy_dem[ii * nnei * 4 + jj * 4 + 0] += res * rr[0] * (nnei - jj);
260	          dy_dem[ii * nnei * 4 + jj * 4 + 1] += res * rr[1] * (nnei - jj);
261	          dy_dem[ii * nnei * 4 + jj * 4 + 2] += res * rr[2] * (nnei - jj);
262	          dy_dem[ii * nnei * 4 + jj * 4 + 3] += res * rr[3] * (nnei - jj);
263	          if (enable_se_atten) {
264	            // fill from jj to nnei
265	            for (int jj2 = jj; jj2 < nnei; jj2++) {
266	              dy_dtwo[ii * nnei * last_layer_size + jj2 * last_layer_size +
267	                      kk] += resold * dotllrr;
268	            }
269	          }
270	        } else {
271	          grad += g * dotllrr;
272	          dy_dem[ii * nnei * 4 + jj * 4 + 0] += res * rr[0];
273	          dy_dem[ii * nnei * 4 + jj * 4 + 1] += res * rr[1];
274	          dy_dem[ii * nnei * 4 + jj * 4 + 2] += res * rr[2];
275	          dy_dem[ii * nnei * 4 + jj * 4 + 3] += res * rr[3];
276	          if (enable_se_atten) {
277	            dy_dtwo[ii * nnei * last_layer_size + jj * last_layer_size + kk] +=
278	                resold * dotllrr;
279	          }
280	        }
281	      }
282	      dy_dem_x[ii * nnei + jj] = grad;
283	      if (unloop) {
284	        break;
285	      }
286	    }
287	  }
288	}
