290	template <typename FPTYPE>
291	void deepmd::tabulate_fusion_se_a_grad_grad_cpu(FPTYPE* dz_dy,
292	                                                const FPTYPE* table,
293	                                                const FPTYPE* table_info,
294	                                                const FPTYPE* em_x,
295	                                                const FPTYPE* em,
296	                                                const FPTYPE* two_embed,
297	                                                const FPTYPE* dz_dy_dem_x,
298	                                                const FPTYPE* dz_dy_dem,
299	                                                const FPTYPE* dz_dy_dtwo,
300	                                                const int nloc,
301	                                                const int nnei,
302	                                                const int last_layer_size,
303	                                                const bool is_sorted) {
304	  bool enable_se_atten = two_embed != nullptr;
305	  memset(dz_dy, 0, sizeof(FPTYPE) * nloc * 4 * last_layer_size);
306	  const FPTYPE lower = table_info[0];
307	  const FPTYPE upper = table_info[1];
308	  const FPTYPE _max = table_info[2];
309	  const FPTYPE stride0 = table_info[3];
310	  const FPTYPE stride1 = table_info[4];
311	// for every atom, execute a small manual gemm ~
312	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
313	#pragma omp parallel for
314	  for (int ii = 0; ii < nloc; ii++) {
315	    FPTYPE ll[4];
316	    FPTYPE hh[4];
317	    FPTYPE ago = em_x[ii * nnei + nnei - 1];
318	    bool unloop = false;
319	    for (int jj = 0; jj < nnei; jj++) {
320	      ll[0] = em[ii * nnei * 4 + jj * 4 + 0];
321	      ll[1] = em[ii * nnei * 4 + jj * 4 + 1];
322	      ll[2] = em[ii * nnei * 4 + jj * 4 + 2];
323	      ll[3] = em[ii * nnei * 4 + jj * 4 + 3];
324	      hh[0] = dz_dy_dem[ii * nnei * 4 + jj * 4 + 0];
325	      hh[1] = dz_dy_dem[ii * nnei * 4 + jj * 4 + 1];
326	      hh[2] = dz_dy_dem[ii * nnei * 4 + jj * 4 + 2];
327	      hh[3] = dz_dy_dem[ii * nnei * 4 + jj * 4 + 3];
328	      FPTYPE xx = em_x[ii * nnei + jj];
329	      FPTYPE dz_xx = dz_dy_dem_x[ii * nnei + jj];
330	      if (ago == xx && ll[1] == 0. && ll[2] == 0. && ll[3] == 0. && is_sorted) {
331	        unloop = true;
332	      }
333	      int table_idx = 0;
334	      locate_xx(lower, upper, _max, stride0, stride1, xx, table_idx);
335	      for (int kk = 0; kk < last_layer_size; kk++) {
336	        FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * kk + 0];
337	        FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * kk + 1];
338	        FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * kk + 2];
339	        FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * kk + 3];
340	        FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * kk + 4];
341	        FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * kk + 5];
342	        FPTYPE var =
343	            a0 + (a1 + (a2 + (a3 + (a4 + a5 * xx) * xx) * xx) * xx) * xx;
344	        FPTYPE var_grad =
345	            a1 +
346	            ((FPTYPE)2. * a2 +
347	             ((FPTYPE)3. * a3 + ((FPTYPE)4. * a4 + (FPTYPE)5. * a5 * xx) * xx) *
348	                 xx) *
349	                xx;
350	        FPTYPE two_grad = 0.;
351	        if (enable_se_atten) {
352	          FPTYPE t = two_embed[ii * nnei * last_layer_size +
353	                               jj * last_layer_size + kk];
354	          // dz_dy_dtwo * var * ll
355	          // var above should be used instead of var + var * t below
356	          two_grad = dz_dy_dtwo[ii * nnei * last_layer_size +
357	                                jj * last_layer_size + kk] *
358	                     var;
359	          var += var * t;
360	          var_grad += var_grad * t;
361	        }
362	
363	        /*
364	         * `dz_dy` represents the derivative of the variable `out` in the
365	         * function `deepmd::tabulate_fusion_se_a_cpu`.
366	         *
367	         * The expression `var * hh[0] + dz_xx * var_grad * ll[0]` utilizes the
368	         * product rule of derivatives: `(f * g)' = f' * g + f * g'`.
369	         *
370	         * This expression can be alternatively expressed as:
371	         * `hh[0] * var + ll[0] * (dz_xx * var_grad)`.
372	         * Note that `hh[0]` is one element of `em`, and `ll[0]` is one element
373	         * of `dz_dy_dem` which is `em'`.
374	         *
375	         * Therefore, we can rewrite this expression as: `em' * var + em *
376	         * var'`, where `em'` is the derivative of `em` and `var'` is the
377	         * derivative of `var`. Additionally, `var'` can be further represented
378	         * as: `var_grad * dz_xx`.
379	         *
380	         * If `enable_se_atten` is true, `var` will be `var * t + var`, and
381	         * `var'` will be `(var_grad * t + var_grad) * dz_xx`.
382	         */
383	        if (unloop) {
384	          dz_dy[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
385	              (nnei - jj) *
386	              (var * hh[0] + (dz_xx * var_grad + two_grad) * ll[0]);
387	          dz_dy[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
388	              (nnei - jj) *
389	              (var * hh[1] + (dz_xx * var_grad + two_grad) * ll[1]);
390	          dz_dy[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
410	    }
411	  }
412	}
