573	template <typename FPTYPE>
574	void deepmd::tabulate_fusion_se_t_tebd_cpu(FPTYPE* out,
575	                                           const FPTYPE* table,
575	                                           const FPTYPE* table,
576	                                           const FPTYPE* table_info,
577	                                           const FPTYPE* em_x,
578	                                           const FPTYPE* em,
579	                                           const int nloc,
580	                                           const int nnei_i,
581	                                           const int nnei_j,
582	                                           const int last_layer_size) {
583	  memset(out, 0, sizeof(FPTYPE) * nloc * nnei_i * nnei_j * last_layer_size);
584	  const FPTYPE lower = table_info[0];
585	  const FPTYPE upper = table_info[1];
586	  const FPTYPE _max = table_info[2];
587	  const FPTYPE stride0 = table_info[3];
588	  const FPTYPE stride1 = table_info[4];
589	
590	#pragma omp parallel for
591	  for (int ii = 0; ii < nloc; ii++) {
592	    for (int jj = 0; jj < nnei_i; jj++) {
593	      for (int kk = 0; kk < nnei_j; kk++) {
594	        FPTYPE xx = em_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
595	        int table_idx = 0;
596	        locate_xx_se_t(lower, upper, -_max, _max, stride0, stride1, xx,
597	                       table_idx);
598	
599	        // For SE_TEBD, we preserve the full nt_i x nt_j x ng structure
600	        // instead of reducing it like SE_T does
601	        for (int mm = 0; mm < last_layer_size; mm++) {
602	          FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * mm + 0];
