template <typename FPTYPE>
inline FPTYPE extrapolated_polynomial(const FPTYPE& a0,
                                      const FPTYPE& a1,
                                      const FPTYPE& a2,
                                      const FPTYPE& a3,
                                      const FPTYPE& a4,
                                      const FPTYPE& a5,
                                      const FPTYPE& xx,
                                      const FPTYPE& extrapolation) {
  const FPTYPE value =
      a0 + (a1 + (a2 + (a3 + (a4 + a5 * xx) * xx) * xx) * xx) * xx;
  const FPTYPE gradient =
      a1 + ((FPTYPE)2. * a2 +
            ((FPTYPE)3. * a3 +
             ((FPTYPE)4. * a4 + (FPTYPE)5. * a5 * xx) * xx) *
                xx) *
               xx;
  return value + extrapolation * gradient;
}

