     8	#include <iostream>
     9	#include <vector>
    10	/*
    11	    This inline function was designed to get the table info and bias value for
    12	   current input xx! lower:      indicate the lower boundary of the first table;
    13	    upper:      indicate the upper boundary of the first table as well as the
    14	   lower boundary of the second table; max:        indicate the upper boundary
    15	   of the second table; stride0:    indicate the stride of the first table;
    16	    stride1:    indicate the stride of the second table;
    17	    xx:         indicate the input value and return the local polynomial
    18	                coordinate;
    19	    table_idx:  indicate the location of table info of input value xx;
    20	    extrapolation: return the signed distance beyond the tabulated support.
    21	                   Values outside the support are continued with the tangent
    22	                   at the nearest endpoint rather than with an unsupported
    23	                   fifth-order polynomial interval.
    24	*/
    25	template <typename FPTYPE>
    26	inline int interval_count(const FPTYPE& begin,
    27	                          const FPTYPE& end,
    28	                          const FPTYPE& stride) {
    29	  assert(stride > (FPTYPE)0.);
    30	  const int count = static_cast<int>(std::llround((end - begin) / stride));
    31	  assert(count >= 0);
    32	  return count;
    33	}
    34	
    35	template <typename FPTYPE>
    36	inline void locate_xx(const FPTYPE& lower,
    37	                      const FPTYPE& upper,
    38	                      const FPTYPE& max,
    39	                      const FPTYPE& stride0,
    40	                      const FPTYPE& stride1,
    41	                      FPTYPE& xx,
    42	                      int& table_idx,
    43	                      FPTYPE& extrapolation) {
    44	  extrapolation = (FPTYPE)0.;
    45	  if (xx < lower) {
    46	    table_idx = 0;
    47	    extrapolation = xx - lower;
    48	    xx = (FPTYPE)0.;
    49	  } else if (xx < upper) {
    50	    table_idx = (int)((xx - lower) / stride0);
    51	    xx -= (table_idx * stride0 + lower);
    52	  } else if (xx < max) {
    53	    const int first_stride = interval_count(lower, upper, stride0);
    54	    table_idx = first_stride + (int)((xx - upper) / stride1);
    55	    xx -= ((table_idx - first_stride) * stride1 + upper);
    56	  } else {
    57	    const int first_stride = interval_count(lower, upper, stride0);
    58	    const int second_stride = interval_count(upper, max, stride1);
    59	    table_idx = first_stride + second_stride - 1;
    60	    assert(table_idx >= 0);
    61	    const FPTYPE interval_start =
    62	        second_stride > 0 ? upper + (second_stride - 1) * stride1
    63	                          : lower + (first_stride - 1) * stride0;
    64	    extrapolation = xx - max;
    65	    xx = max - interval_start;
    66	  }
    67	}
    68	
    69	template <typename FPTYPE>
    70	inline void locate_xx_se_t(const FPTYPE& lower,
    71	                           const FPTYPE& upper,
    72	                           const FPTYPE& min,
    73	                           const FPTYPE& max,
    74	                           const FPTYPE& stride0,
    75	                           const FPTYPE& stride1,
    76	                           FPTYPE& xx,
    77	                           int& table_idx,
    78	                           FPTYPE& extrapolation) {
    79	  extrapolation = (FPTYPE)0.;
    80	  if (xx < min) {
    81	    table_idx = 0;
    82	    extrapolation = xx - min;
    83	    xx = (FPTYPE)0.;
    84	  } else if (xx < lower) {
    85	    table_idx = (int)((xx - min) / stride1);
    86	    xx -= (table_idx * stride1 + min);
    87	  } else if (xx < upper) {
    88	    const int first_stride = interval_count(min, lower, stride1);
    89	    table_idx = first_stride + (int)((xx - lower) / stride0);
    90	    xx -= ((table_idx - first_stride) * stride0 + lower);
    91	  } else if (xx < max) {
    92	    const int first_stride = interval_count(min, lower, stride1) +
    93	                             interval_count(lower, upper, stride0);
    94	    table_idx = first_stride + (int)((xx - upper) / stride1);
    95	    xx -= ((table_idx - first_stride) * stride1 + upper);
    96	  } else {
    97	    const int first_stride = interval_count(min, lower, stride1);
    98	    const int second_stride = interval_count(lower, upper, stride0);
    99	    const int third_stride = interval_count(upper, max, stride1);
   100	    table_idx = first_stride + second_stride + third_stride - 1;
   101	    assert(table_idx >= 0);
   102	    FPTYPE interval_start;
   103	    if (third_stride > 0) {
   104	      interval_start = upper + (third_stride - 1) * stride1;
   105	    } else if (second_stride > 0) {
   106	      interval_start = lower + (second_stride - 1) * stride0;
   107	    } else {
   108	      interval_start = min + (first_stride - 1) * stride1;
   109	    }
   110	    extrapolation = xx - max;
   111	    xx = max - interval_start;
   112	  }
   113	}
