   115	template <typename FPTYPE>
   116	inline FPTYPE dot(FPTYPE a[4], FPTYPE b[4]) {
   117	  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2] + a[3] * b[3];
   118	}
   119	
   120	template <typename FPTYPE>
   121	inline FPTYPE polynomial_gradient(const FPTYPE& a1,
   122	                                  const FPTYPE& a2,
   123	                                  const FPTYPE& a3,
   124	                                  const FPTYPE& a4,
   125	                                  const FPTYPE& a5,
   126	                                  const FPTYPE& xx) {
   127	  return a1 + ((FPTYPE)2. * a2 +
   128	               ((FPTYPE)3. * a3 +
   129	                ((FPTYPE)4. * a4 + (FPTYPE)5. * a5 * xx) * xx) *
   130	                   xx) *
   131	                  xx;
   132	}
   133	
   134	template <typename FPTYPE>
   135	inline FPTYPE extrapolated_polynomial(const FPTYPE& a0,
   136	                                      const FPTYPE& a1,
   137	                                      const FPTYPE& a2,
   138	                                      const FPTYPE& a3,
   139	                                      const FPTYPE& a4,
   140	                                      const FPTYPE& a5,
   141	                                      const FPTYPE& xx,
   142	                                      const FPTYPE& extrapolation) {
   143	  const FPTYPE value =
   144	      a0 + (a1 + (a2 + (a3 + (a4 + a5 * xx) * xx) * xx) * xx) * xx;
   145	  return value + extrapolation * polynomial_gradient(a1, a2, a3, a4, a5, xx);
   146	}
