   148	template <typename FPTYPE>
   149	void deepmd::tabulate_fusion_se_a_cpu(FPTYPE* out,
   150	                                      const FPTYPE* table,
   150	                                      const FPTYPE* table,
   151	                                      const FPTYPE* table_info,
   152	                                      const FPTYPE* em_x,
   153	                                      const FPTYPE* em,
   154	                                      const FPTYPE* two_embed,
   155	                                      const int nloc,
   156	                                      const int nnei,
   157	                                      const int last_layer_size,
   158	                                      const bool is_sorted) {
   159	  bool enable_se_atten = two_embed != nullptr;
   160	  memset(out, 0, sizeof(FPTYPE) * nloc * 4 * last_layer_size);
   161	  const FPTYPE lower = table_info[0];
   162	  const FPTYPE upper = table_info[1];
   163	  const FPTYPE _max = table_info[2];
   164	  const FPTYPE stride0 = table_info[3];
   165	  const FPTYPE stride1 = table_info[4];
   166	// for every atom, execute a small manual gemm ~
   167	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
   168	#pragma omp parallel for
   169	  for (int ii = 0; ii < nloc; ii++) {
   170	    FPTYPE ll[4] = {0};
   171	    FPTYPE ago = em_x[ii * nnei + nnei - 1];
   172	    bool unloop = false;
   173	    for (int jj = 0; jj < nnei; jj++) {
   174	      ll[0] = em[ii * nnei * 4 + jj * 4 + 0];
   175	      ll[1] = em[ii * nnei * 4 + jj * 4 + 1];
   176	      ll[2] = em[ii * nnei * 4 + jj * 4 + 2];
   177	      ll[3] = em[ii * nnei * 4 + jj * 4 + 3];
   178	      FPTYPE xx = em_x[ii * nnei + jj];
   179	      if (ago == xx && ll[1] == 0. && ll[2] == 0. && ll[3] == 0. && is_sorted) {
   180	        unloop = true;
   181	      }
   182	      int table_idx = 0;
   183	      FPTYPE extrapolation;
   184	      locate_xx(lower, upper, _max, stride0, stride1, xx, table_idx,
   185	                extrapolation);
   186	      for (int kk = 0; kk < last_layer_size; kk++) {
   187	        FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * kk + 0];
   188	        FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * kk + 1];
   189	        FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * kk + 2];
   190	        FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * kk + 3];
   191	        FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * kk + 4];
   192	        FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * kk + 5];
   193	        FPTYPE var =
   194	            extrapolated_polynomial(a0, a1, a2, a3, a4, a5, xx, extrapolation);
   195	        if (enable_se_atten) {
   196	          FPTYPE t = two_embed[ii * nnei * last_layer_size +
   197	                               jj * last_layer_size + kk];
   198	          var = var * t + var;
   199	        }
   200	
   201	        if (unloop) {
   202	          out[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
   203	              (nnei - jj) * var * ll[0];
   204	          out[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
   205	              (nnei - jj) * var * ll[1];
   206	          out[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
   207	              (nnei - jj) * var * ll[2];
   208	          out[ii * last_layer_size * 4 + 3 * last_layer_size + kk] +=
   209	              (nnei - jj) * var * ll[3];
   210	        } else {
   211	          out[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
   212	              var * ll[0];
   213	          out[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
   214	              var * ll[1];
   215	          out[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
   216	              var * ll[2];
   217	          out[ii * last_layer_size * 4 + 3 * last_layer_size + kk] +=
   218	              var * ll[3];
   219	        }
   220	      }
   221	      if (unloop) {
   222	        break;
   223	      }
   224	    }
   225	  }
   226	}
