   228	template <typename FPTYPE>
   229	void deepmd::tabulate_fusion_se_a_grad_cpu(FPTYPE* dy_dem_x,
   230	                                           FPTYPE* dy_dem,
   231	                                           FPTYPE* dy_dtwo,
   232	                                           const FPTYPE* table,
   233	                                           const FPTYPE* table_info,
   234	                                           const FPTYPE* em_x,
   235	                                           const FPTYPE* em,
   236	                                           const FPTYPE* two_embed,
   237	                                           const FPTYPE* dy,
   238	                                           const int nloc,
   239	                                           const int nnei,
   240	                                           const int last_layer_size,
   241	                                           const bool is_sorted) {
   242	  bool enable_se_atten = two_embed != nullptr;
   243	  memset(dy_dem_x, 0, sizeof(FPTYPE) * nloc * nnei);
   244	  memset(dy_dem, 0, sizeof(FPTYPE) * nloc * nnei * 4);
   245	  if (enable_se_atten) {
   246	    memset(dy_dtwo, 0, sizeof(FPTYPE) * nloc * nnei * last_layer_size);
   247	  }
   248	  FPTYPE const lower = table_info[0];
   249	  FPTYPE const upper = table_info[1];
   250	  FPTYPE const _max = table_info[2];
   251	  FPTYPE const stride0 = table_info[3];
   252	  FPTYPE const stride1 = table_info[4];
   253	// for every atom, execute a small gemm~
   254	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
   255	#pragma omp parallel for
   256	  for (int ii = 0; ii < nloc; ii++) {
   257	    FPTYPE ll[4];
   258	    FPTYPE rr[4];
   259	    FPTYPE ago = em_x[ii * nnei + nnei - 1];
   260	    bool unloop = false;
   261	    for (int jj = 0; jj < nnei; jj++) {
   262	      // construct the dy/dx
   263	      ll[0] = em[ii * nnei * 4 + jj * 4 + 0];
   264	      ll[1] = em[ii * nnei * 4 + jj * 4 + 1];
   265	      ll[2] = em[ii * nnei * 4 + jj * 4 + 2];
   266	      ll[3] = em[ii * nnei * 4 + jj * 4 + 3];
   267	      FPTYPE xx = em_x[ii * nnei + jj];
   268	      if (ago == xx && ll[1] == 0. && ll[2] == 0. && ll[3] == 0. && is_sorted) {
   269	        unloop = true;
   270	      }
   271	      int table_idx = 0;
   272	      FPTYPE extrapolation;
   273	      locate_xx(lower, upper, _max, stride0, stride1, xx, table_idx,
   274	                extrapolation);
   275	      FPTYPE grad = (FPTYPE)0.0;
   276	      for (int kk = 0; kk < last_layer_size; kk++) {
   277	        rr[0] = dy[ii * last_layer_size * 4 + 0 * last_layer_size + kk];
   278	        rr[1] = dy[ii * last_layer_size * 4 + 1 * last_layer_size + kk];
   279	        rr[2] = dy[ii * last_layer_size * 4 + 2 * last_layer_size + kk];
   280	        rr[3] = dy[ii * last_layer_size * 4 + 3 * last_layer_size + kk];
   281	        FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * kk + 0];
   282	        FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * kk + 1];
   283	        FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * kk + 2];
   284	        FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * kk + 3];
   285	        FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * kk + 4];
   286	        FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * kk + 5];
   287	        FPTYPE res =
   288	            extrapolated_polynomial(a0, a1, a2, a3, a4, a5, xx, extrapolation);
   289	        FPTYPE g = polynomial_gradient(a1, a2, a3, a4, a5, xx);
   290	        FPTYPE resold = res;
   291	        if (enable_se_atten) {
   292	          FPTYPE t = two_embed[ii * nnei * last_layer_size +
   293	                               jj * last_layer_size + kk];
   294	          res = res * t + res;
   295	          g += t * g;
   296	        }
   297	
   298	        FPTYPE dotllrr = dot(ll, rr);
   299	        if (unloop) {
   300	          grad += g * dotllrr * (nnei - jj);
   301	          dy_dem[ii * nnei * 4 + jj * 4 + 0] += res * rr[0] * (nnei - jj);
   302	          dy_dem[ii * nnei * 4 + jj * 4 + 1] += res * rr[1] * (nnei - jj);
   303	          dy_dem[ii * nnei * 4 + jj * 4 + 2] += res * rr[2] * (nnei - jj);
   304	          dy_dem[ii * nnei * 4 + jj * 4 + 3] += res * rr[3] * (nnei - jj);
   305	          if (enable_se_atten) {
   306	            // fill from jj to nnei
   307	            for (int jj2 = jj; jj2 < nnei; jj2++) {
   308	              dy_dtwo[ii * nnei * last_layer_size + jj2 * last_layer_size +
   309	                      kk] += resold * dotllrr;
   310	            }
   350	  const FPTYPE _max = table_info[2];
   351	  const FPTYPE stride0 = table_info[3];
   352	  const FPTYPE stride1 = table_info[4];
   353	// for every atom, execute a small manual gemm ~
   354	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
   355	#pragma omp parallel for
   356	  for (int ii = 0; ii < nloc; ii++) {
   357	    FPTYPE ll[4];
   358	    FPTYPE hh[4];
   359	    FPTYPE ago = em_x[ii * nnei + nnei - 1];
   360	    bool unloop = false;
   361	    for (int jj = 0; jj < nnei; jj++) {
   362	      ll[0] = em[ii * nnei * 4 + jj * 4 + 0];
   363	      ll[1] = em[ii * nnei * 4 + jj * 4 + 1];
   364	      ll[2] = em[ii * nnei * 4 + jj * 4 + 2];
   365	      ll[3] = em[ii * nnei * 4 + jj * 4 + 3];
   366	      hh[0] = dz_dy_dem[ii * nnei * 4 + jj * 4 + 0];
   367	      hh[1] = dz_dy_dem[ii * nnei * 4 + jj * 4 + 1];
   368	      hh[2] = dz_dy_dem[ii * nnei * 4 + jj * 4 + 2];
   369	      hh[3] = dz_dy_dem[ii * nnei * 4 + jj * 4 + 3];
   370	      FPTYPE xx = em_x[ii * nnei + jj];
   371	      FPTYPE dz_xx = dz_dy_dem_x[ii * nnei + jj];
   372	      if (ago == xx && ll[1] == 0. && ll[2] == 0. && ll[3] == 0. && is_sorted) {
   373	        unloop = true;
   374	      }
   375	      int table_idx = 0;
   376	      FPTYPE extrapolation;
   377	      locate_xx(lower, upper, _max, stride0, stride1, xx, table_idx,
   378	                extrapolation);
   379	      for (int kk = 0; kk < last_layer_size; kk++) {
   380	        FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * kk + 0];
   381	        FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * kk + 1];
   382	        FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * kk + 2];
   383	        FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * kk + 3];
   384	        FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * kk + 4];
   385	        FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * kk + 5];
   386	        FPTYPE var =
   387	            extrapolated_polynomial(a0, a1, a2, a3, a4, a5, xx, extrapolation);
   388	        FPTYPE var_grad = polynomial_gradient(a1, a2, a3, a4, a5, xx);
   389	        FPTYPE two_grad = 0.;
   390	        if (enable_se_atten) {
   391	          FPTYPE t = two_embed[ii * nnei * last_layer_size +
   392	                               jj * last_layer_size + kk];
   393	          // dz_dy_dtwo * var * ll
   394	          // var above should be used instead of var + var * t below
   395	          two_grad = dz_dy_dtwo[ii * nnei * last_layer_size +
   396	                                jj * last_layer_size + kk] *
   397	                     var;
   398	          var += var * t;
   399	          var_grad += var_grad * t;
   400	        }
   401	
   402	        /*
   403	         * `dz_dy` represents the derivative of the variable `out` in the
   404	         * function `deepmd::tabulate_fusion_se_a_cpu`.
   405	         *
   406	         * The expression `var * hh[0] + dz_xx * var_grad * ll[0]` utilizes the
   407	         * product rule of derivatives: `(f * g)' = f' * g + f * g'`.
   408	         *
   409	         * This expression can be alternatively expressed as:
   410	         * `hh[0] * var + ll[0] * (dz_xx * var_grad)`.
   411	         * Note that `hh[0]` is one element of `em`, and `ll[0]` is one element
   412	         * of `dz_dy_dem` which is `em'`.
   413	         *
   414	         * Therefore, we can rewrite this expression as: `em' * var + em *
   415	         * var'`, where `em'` is the derivative of `em` and `var'` is the
   416	         * derivative of `var`. Additionally, `var'` can be further represented
   417	         * as: `var_grad * dz_xx`.
   418	         *
   419	         * If `enable_se_atten` is true, `var` will be `var * t + var`, and
   420	         * `var'` will be `(var_grad * t + var_grad) * dz_xx`.
   421	         */
   422	        if (unloop) {
   423	          dz_dy[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
   424	              (nnei - jj) *
   425	              (var * hh[0] + (dz_xx * var_grad + two_grad) * ll[0]);
   426	          dz_dy[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
   427	              (nnei - jj) *
   428	              (var * hh[1] + (dz_xx * var_grad + two_grad) * ll[1]);
   429	          dz_dy[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
   430	              (nnei - jj) *
   431	              (var * hh[2] + (dz_xx * var_grad + two_grad) * ll[2]);
   432	          dz_dy[ii * last_layer_size * 4 + 3 * last_layer_size + kk] +=
   433	              (nnei - jj) *
   434	              (var * hh[3] + (dz_xx * var_grad + two_grad) * ll[3]);
   435	        } else {
   436	          dz_dy[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
   437	              var * hh[0] + (dz_xx * var_grad + two_grad) * ll[0];
   438	          dz_dy[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
   439	              var * hh[1] + (dz_xx * var_grad + two_grad) * ll[1];
   440	          dz_dy[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
   441	              var * hh[2] + (dz_xx * var_grad + two_grad) * ll[2];
   442	          dz_dy[ii * last_layer_size * 4 + 3 * last_layer_size + kk] +=
   443	              var * hh[3] + (dz_xx * var_grad + two_grad) * ll[3];
   444	        }
   445	      }
   446	      if (unloop) {
   447	        break;
   448	      }
   449	    }
   450	  }
   451	}
