   453	template <typename FPTYPE>
   454	void deepmd::tabulate_fusion_se_t_cpu(FPTYPE* out,
   455	                                      const FPTYPE* table,
   460	                                      const int nnei_i,
   461	                                      const int nnei_j,
   462	                                      const int last_layer_size) {
   463	  memset(out, 0, sizeof(FPTYPE) * nloc * last_layer_size);
   464	  const FPTYPE lower = table_info[0];
   465	  const FPTYPE upper = table_info[1];
   466	  const FPTYPE _max = table_info[2];
   467	  const FPTYPE stride0 = table_info[3];
   468	  const FPTYPE stride1 = table_info[4];
   469	// for every atom, execute a small manual gemm ~
   470	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
   471	#pragma omp parallel for
   472	  for (int ii = 0; ii < nloc; ii++) {
   473	    for (int jj = 0; jj < nnei_i; jj++) {
   474	      // unloop not work as em_x is not sorted
   475	      for (int kk = 0; kk < nnei_j; kk++) {
   476	        FPTYPE xx = em_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
   477	        FPTYPE ll = xx;
   478	        int table_idx = 0;
   479	        FPTYPE extrapolation;
   480	        locate_xx_se_t(lower, upper, -_max, _max, stride0, stride1, xx,
   481	                       table_idx, extrapolation);
   482	        for (int mm = 0; mm < last_layer_size; mm++) {
   483	          FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * mm + 0];
   484	          FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * mm + 1];
   485	          FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * mm + 2];
   486	          FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * mm + 3];
   487	          FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * mm + 4];
   488	          FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * mm + 5];
   489	          FPTYPE var = extrapolated_polynomial(a0, a1, a2, a3, a4, a5, xx,
   490	                                               extrapolation);
   491	          out[ii * last_layer_size + mm] += var * ll;
   492	        }
   493	      }
   494	    }
   495	  }
   496	}
