   498	template <typename FPTYPE>
   499	void deepmd::tabulate_fusion_se_t_grad_cpu(FPTYPE* dy_dem_x,
   500	                                           FPTYPE* dy_dem,
   501	                                           const FPTYPE* table,
   502	                                           const FPTYPE* table_info,
   503	                                           const FPTYPE* em_x,
   504	                                           const FPTYPE* em,
   505	                                           const FPTYPE* dy,
   506	                                           const int nloc,
   507	                                           const int nnei_i,
   508	                                           const int nnei_j,
   509	                                           const int last_layer_size) {
   510	  memset(dy_dem_x, 0, sizeof(FPTYPE) * nloc * nnei_i * nnei_j);
   511	  memset(dy_dem, 0, sizeof(FPTYPE) * nloc * nnei_i * nnei_j);
   512	  FPTYPE const lower = table_info[0];
   513	  FPTYPE const upper = table_info[1];
   514	  FPTYPE const _max = table_info[2];
   515	  FPTYPE const stride0 = table_info[3];
   516	  FPTYPE const stride1 = table_info[4];
   517	// for every atom, execute a small gemm~
   518	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
   519	#pragma omp parallel for
   520	  for (int ii = 0; ii < nloc; ii++) {
   521	    FPTYPE ll = (FPTYPE)0.;
   522	    FPTYPE rr = (FPTYPE)0.;
   523	    for (int jj = 0; jj < nnei_i; jj++) {
   524	      for (int kk = 0; kk < nnei_j; kk++) {
   525	        // construct the dy/dx
   526	        FPTYPE xx = em_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
   527	        ll = xx;
   528	        int table_idx = 0;
   529	        FPTYPE extrapolation;
   530	        locate_xx_se_t(lower, upper, -_max, _max, stride0, stride1, xx,
   531	                       table_idx, extrapolation);
   532	        FPTYPE grad = (FPTYPE)0.0;
   533	        for (int mm = 0; mm < last_layer_size; mm++) {
   534	          rr = dy[ii * last_layer_size + mm];
   535	          FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * mm + 0];
   536	          FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * mm + 1];
   537	          FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * mm + 2];
   538	          FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * mm + 3];
   539	          FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * mm + 4];
   540	          FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * mm + 5];
   541	          FPTYPE res = extrapolated_polynomial(a0, a1, a2, a3, a4, a5, xx,
   542	                                               extrapolation);
   543	
   544	          grad += polynomial_gradient(a1, a2, a3, a4, a5, xx) * ll * rr;
   545	          dy_dem[ii * nnei_i * nnei_j + jj * nnei_j + kk] += res * rr;
   546	        }
   547	        dy_dem_x[ii * nnei_i * nnei_j + jj * nnei_j + kk] = grad;
   548	      }
   549	    }
   550	  }
   551	}
