   553	template <typename FPTYPE>
   554	void deepmd::tabulate_fusion_se_t_grad_grad_cpu(FPTYPE* dz_dy,
   555	                                                const FPTYPE* table,
   556	                                                const FPTYPE* table_info,
   557	                                                const FPTYPE* em_x,
   558	                                                const FPTYPE* em,
   559	                                                const FPTYPE* dz_dy_dem_x,
   560	                                                const FPTYPE* dz_dy_dem,
   561	                                                const int nloc,
   562	                                                const int nnei_i,
   563	                                                const int nnei_j,
   564	                                                const int last_layer_size) {
   565	  memset(dz_dy, 0, sizeof(FPTYPE) * nloc * last_layer_size);
   566	  const FPTYPE lower = table_info[0];
   567	  const FPTYPE upper = table_info[1];
   568	  const FPTYPE _max = table_info[2];
   569	  const FPTYPE stride0 = table_info[3];
   570	  const FPTYPE stride1 = table_info[4];
   571	// for every atom, execute a small manual gemm ~
   572	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
   573	#pragma omp parallel for
   574	  for (int ii = 0; ii < nloc; ii++) {
   575	    for (int jj = 0; jj < nnei_i; jj++) {
   576	      for (int kk = 0; kk < nnei_j; kk++) {
   577	        FPTYPE xx = em_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
   578	        FPTYPE tmp = xx;
   579	        FPTYPE dz_em = dz_dy_dem[ii * nnei_i * nnei_j + jj * nnei_j + kk];
   580	        FPTYPE dz_xx = dz_dy_dem_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
   581	
   582	        int table_idx = 0;
   583	        FPTYPE extrapolation;
   584	        locate_xx_se_t(lower, upper, -_max, _max, stride0, stride1, xx,
   585	                       table_idx, extrapolation);
   586	        for (int mm = 0; mm < last_layer_size; mm++) {
   587	          FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * mm + 0];
   588	          FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * mm + 1];
   589	          FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * mm + 2];
   590	          FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * mm + 3];
   591	          FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * mm + 4];
   592	          FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * mm + 5];
   593	          FPTYPE var = extrapolated_polynomial(a0, a1, a2, a3, a4, a5, xx,
   594	                                               extrapolation);
   595	          FPTYPE var_grad = polynomial_gradient(a1, a2, a3, a4, a5, xx);
   596	
   597	          dz_dy[ii * last_layer_size + mm] +=
   598	              var * dz_em + dz_xx * var_grad * tmp;
   599	        }
   600	      }
   601	    }
   602	  }
   603	}
