   605	template <typename FPTYPE>
   606	void deepmd::tabulate_fusion_se_t_tebd_cpu(FPTYPE* out,
   607	                                           const FPTYPE* table,
   608	                                           const FPTYPE* table_info,
   609	                                           const FPTYPE* em_x,
   610	                                           const FPTYPE* em,
   611	                                           const int nloc,
   612	                                           const int nnei_i,
   613	                                           const int nnei_j,
   614	                                           const int last_layer_size) {
   615	  memset(out, 0, sizeof(FPTYPE) * nloc * nnei_i * nnei_j * last_layer_size);
   616	  const FPTYPE lower = table_info[0];
   617	  const FPTYPE upper = table_info[1];
   618	  const FPTYPE _max = table_info[2];
   619	  const FPTYPE stride0 = table_info[3];
   620	  const FPTYPE stride1 = table_info[4];
   621	
   622	#pragma omp parallel for
   623	  for (int ii = 0; ii < nloc; ii++) {
   624	    for (int jj = 0; jj < nnei_i; jj++) {
   625	      for (int kk = 0; kk < nnei_j; kk++) {
   626	        FPTYPE xx = em_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
   627	        int table_idx = 0;
   628	        FPTYPE extrapolation;
   629	        locate_xx_se_t(lower, upper, -_max, _max, stride0, stride1, xx,
   630	                       table_idx, extrapolation);
   631	
   632	        // For SE_TEBD, we preserve the full nt_i x nt_j x ng structure
   633	        // instead of reducing it like SE_T does
   634	        for (int mm = 0; mm < last_layer_size; mm++) {
   635	          FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * mm + 0];
   636	          FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * mm + 1];
   637	          FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * mm + 2];
   638	          FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * mm + 3];
   639	          FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * mm + 4];
   640	          FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * mm + 5];
   641	
   642	          FPTYPE res = extrapolated_polynomial(a0, a1, a2, a3, a4, a5, xx,
   643	                                               extrapolation);
   644	
   645	          // Store result preserving the nt_i x nt_j structure
   646	          out[ii * nnei_i * nnei_j * last_layer_size +
   647	              jj * nnei_j * last_layer_size + kk * last_layer_size + mm] = res;
   648	        }
   649	      }
   650	    }
   651	  }
   652	}
