   654	template <typename FPTYPE>
   655	void deepmd::tabulate_fusion_se_t_tebd_grad_cpu(FPTYPE* dy_dem_x,
   656	                                                const FPTYPE* table,
   657	                                                const FPTYPE* table_info,
   658	                                                const FPTYPE* em_x,
   659	                                                const FPTYPE* em,
   660	                                                const FPTYPE* dy,
