   669	  const FPTYPE stride0 = table_info[3];
   670	  const FPTYPE stride1 = table_info[4];
   671	
   672	#pragma omp parallel for
   673	  for (int ii = 0; ii < nloc; ii++) {
   674	    for (int jj = 0; jj < nnei_i; jj++) {
   675	      for (int kk = 0; kk < nnei_j; kk++) {
   676	        FPTYPE xx = em_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
