   678	        FPTYPE extrapolation;
   679	        locate_xx_se_t(lower, upper, -_max, _max, stride0, stride1, xx,
   680	                       table_idx, extrapolation);
   681	
   682	        FPTYPE grad_sum = 0.0;
   683	        for (int mm = 0; mm < last_layer_size; mm++) {
   684	          FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * mm + 1];
   685	          FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * mm + 2];
